import {esc} from './visuals.mjs';
import {observeScene,wearableAlert,delivery,validity,stamp,workerStatus} from './safety-model.mjs';
const button=(label,action,id='',className='',disabled=false)=>'<button class="watch-button '+className+'" data-ws="'+action+'" data-value="'+esc(id)+'" '+(disabled?'disabled':'')+'>'+label+'</button>';
export function renderWearable(site,workerView=false){
  const status=workerStatus(site);const alert=wearableAlert(site),capability=delivery(site),degraded=validity(site)==='degraded';
  const urgent=alert?.severity==='high'&&alert.condition,unread=alert&&!alert.acknowledged;
  return '<div class="apple-watch-demo '+(workerView?'worker-watch':'')+'" aria-label="Apple Watch-style simulated worker device"><div class="watch-band top"></div><div class="watch-housing"><span class="watch-crown" aria-hidden="true"></span><div class="watch-screen '+(unread?'watch-notifying':'')+' '+(urgent?'watch-urgent':'')+'"><div class="watch-status"><span>'+esc(site.worker.id)+' · '+site.worker.battery+'%</span><time>'+stamp(site.clock).slice(0,5)+'</time></div><div class="watch-app-label">RPM SAFETY <span>'+(capability==='delivered'?'CONNECTED':'CHECK LINK')+'</span></div>'+(workerView?'<div class="watch-worker-status"><strong>'+esc(site.worker.name)+'</strong><span>'+esc(status.label)+'</span><div><b>'+site.worker.bpm+'<small> bpm</small></b><b>'+Math.floor(site.worker.duty)+'<small> min</small></b></div><p>Heart rate · Continuous work</p></div>':'')+'<div class="watch-notification" role="status" aria-live="assertive"><div class="watch-symbol">'+(alert?'!':degraded?'?':'✓')+'</div><span class="watch-overline">'+(alert?(alert.acknowledged?'RECEIPT CONFIRMED':'ALERT DELIVERED'):degraded?'PROTECTION DEGRADED':workerView?'WORKER STATUS':'MONITORING SCENE')+'</span><strong>'+(alert?esc(alert.title):degraded?'Check the protection system':workerView?'On duty':'Ready for alerts')+'</strong><p>'+(alert?(alert.condition?'Trigger is active. Follow the site response procedure.':'Trigger cleared; review remains pending.'):capability!=='delivered'?'Alert delivery is '+(capability==='failed'?'unavailable.':'uncertain.'):workerView?'Monitoring your shift. Use the watch to request support.':'An alert will appear here automatically when a trigger is detected.')+'</p>'+(alert?'<small>Received '+stamp(alert.lastNotifiedAt??alert.created)+' · '+esc(alert.id)+'</small>':'')+'</div>'+(alert?button(alert.acknowledged?'Acknowledged':'Acknowledge alert','ack',alert.id,'watch-ack',alert.acknowledged):'')+'<div class="watch-actions">'+button('SOS','sos','','watch-sos')+button('Request break','rest','','watch-rest')+'</div><div class="watch-channel">'+(unread?'Haptic · sound · banner':'Local alert link')+' <span>SIMULATED</span></div></div></div><div class="watch-band bottom"></div></div><p class="watch-caption">Apple Watch-style interface. No Apple Watch or physical haptic / sound output is connected.</p>';
}
export function renderObservation(site){
  const o=observeScene(site),v=o.vehicle,p=o.person,north=site.layout.workerZone==='north';
  const observed=site.edge&&site.layout.power&&!site.occluded,danger=o.triggered&&observed;
  const zone=site.case==='approach'?o.warning:site.case==='speed'?o.speedZone:o.restricted;
  const zoneLabel=site.case==='approach'?'Approach warning area':site.case==='speed'?'Speed observation area':'Restricted work zone';
  const box=(r,fill,stroke,dashed='')=>'<rect x="'+r.x+'" y="'+r.y+'" width="'+r.w+'" height="'+r.h+'" fill="'+fill+'" stroke="'+stroke+'" stroke-width="2" '+(dashed?'stroke-dasharray="'+dashed+'"':'')+'/>';
  const workerY=north?43:314;
  return '<svg class="ws-scene ws-moving-scene" viewBox="0 0 800 370" role="img" aria-label="Moving simulated '+esc(site.case)+' scenario; alert activates when the object overlaps its marked trigger area"><rect width="800" height="370" fill="#e6eee8"/><path d="M0 175H800'+(site.layout.template==='corner'?' M390 0V175':'')+'" fill="none" stroke="#576b72" stroke-width="105"/><path d="M0 175H800" stroke="#c7d4d4" stroke-width="2" stroke-dasharray="15 12"/>'+box(o.restricted,'#f5c85b66','#b18b31')+(site.case!=='normal'?box(zone,danger?'#e5796044':'#ecb95219',danger?'#c64e38':'#c29337','7 4'):'')+'<text x="'+zone.x+'" y="'+(zone.y-10)+'" fill="#865e23" font-size="13">'+esc(zoneLabel)+'</text><rect x="482" y="'+(workerY-18)+'" width="250" height="38" rx="5" fill="#fff9db" stroke="#d1b349"/><circle cx="520" cy="'+workerY+'" r="8" fill="#ebbd2a" stroke="#836d30"/><text x="539" y="'+(workerY+4)+'" fill="#786122" font-size="13">Worker zone · '+esc(site.worker.id)+'</text><g transform="translate('+v.x.toFixed(2)+' '+v.y.toFixed(2)+')"><rect x="-32" y="-12" width="64" height="24" rx="5" fill="'+(danger&&site.case!=='pedestrian'?'#ed795f':'#edf5f4')+'"/><rect x="-38" y="-19" width="76" height="38" rx="3" fill="none" stroke="'+(danger&&site.case!=='pedestrian'?'#ffad92':'#75d9c0')+'" stroke-width="2"/><text x="-38" y="-29" fill="#f8fbfb" font-size="13">V-01'+(site.case==='speed'?' · 52 km/h (simulated)':'')+'</text></g>'+(site.case==='pedestrian'?'<g transform="translate('+p.x+' '+p.y.toFixed(2)+')"><rect x="-13" y="-12" width="26" height="47" rx="3" fill="none" stroke="'+(danger?'#cc663a':'#476d5c')+'" stroke-width="2"/><circle cy="-1" r="7" fill="#f2c65d" stroke="#7e6234"/><path d="M0 7v17m-9 -7 9 -9 9 9m-9 7 -7 10m7 -10 7 10" fill="none" stroke="#bd873f" stroke-width="3"/><text x="20" y="5" font-size="13" fill="#6e541f">P-01</text></g>':'')+'<rect x="16" y="12" width="330" height="29" rx="4" fill="#102e35eb"/><text x="28" y="32" fill="#dbecea" font-size="13">SIMULATED REPLAY · '+site.replay.toFixed(1)+' / 18 s</text><rect x="16" y="333" width="768" height="25" rx="4" fill="'+(danger?'#b14e37':'#fffaf0')+'"/><text x="28" y="350" fill="'+(danger?'white':'#6b6f51')+'" font-size="13">'+(danger?'TRIGGER DETECTED · notification sent automatically ('+delivery(site)+')':site.case==='normal'?'Normal passage · no hazard trigger':site.replay>=18?'Replay finished · event records remain available':'Waiting for the moving object to reach the marked trigger area')+'</text>'+(!observed?'<rect width="800" height="370" fill="#152f3be8"/><text x="400" y="175" text-anchor="middle" fill="white" font-size="22">Observation unavailable</text><text x="400" y="205" text-anchor="middle" fill="#c1d2d7" font-size="14">Last known events retained. Restore equipment or visibility.</text>':'')+'</svg>';
}
